// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFee, uint16 feeRate) public {
        vm.assume(uint256(changeFee) != uint256(uint56(feeRate)));
        vm.assume(feeRate <= 5_000);
        c.initialize(
            address(0),
            address(0),
            1e18,
            1e18,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );
        assertTrue(c.changeFee() == changeFee && c.feeRate() == feeRate);
    }
}
